algorithms.pseudocode:
def get(id):
  k = f'p:v3:{id}'
  v = L1.get(k)
  if v and not v.expired(): return v
  if breaker.allow():
    try:
      v = redis.get(k, timeout=20ms); breaker.ok()
      if v: L1.put(k, v, ttl=5s); maybe_early_refresh(k, v); return v
    except Timeout: breaker.fail()
  return singleflight.do(k, lambda: load(id, k))

def load(id, k):
  if not redis.set(k+':lock', token, nx=True, px=3000):
    stale = L1.get_stale(k)
    if stale: return stale
    sleep(20ms); return redis.get(k) or db_read(id)
  row = bulkhead.run(lambda: db.read_replica(id))
  ttl = 600 + random(0, 60)
  redis.set(k, row or NULL_MARKER, ex = ttl if row else 30)
  redis.del_if_owner(k+':lock', token)
  L1.put(k, row, ttl=5s); return row

def maybe_early_refresh(k, entry):
  # entry.delta = seconds the last recompute took
  now = time()
  if now - entry.delta * BETA * log(random()) >= entry.expiry:
    async_refresh(k)   # background, guarded by single-flight

R = 8
def read_hot(k):
  return redis.get(f'{k}#{randint(0, R-1)}')
def write_hot(k, v, ttl):
  pipeline([SET(f'{k}#{i}', v, ex=ttl) for i in range(R)])
def invalidate_hot(k):
  pipeline([DEL(f'{k}#{i}') for i in range(R)])
